// TASK-030e4: the ghost steering decision. The 48 routines of the original ($8E1E-$96E7) are available as a mechanical C++ transliteration
// (ghostdecide_gen.cpp, generated by tools/gen_ghost_decisions.py): ghostDecisionRun() runs the routine that starts at the original address `entry` (from the routine
// address table at $8DBE of the data pack) and returns the new direction (0 down, 1 up, 2 right, 3 left).
#pragma once

#include <cstdint>

namespace pacman::core {

// The only memory the routines read or write.
struct DecisionEnv {
    std::uint8_t ghostX = 0, ghostY = 0;   // $70, $71
    std::uint8_t ghostDir = 0;             // $72 (a few routines set it)
    std::uint8_t pacDir = 0;               // $62: Pac-Man's direction
    std::uint8_t pacTunnel = 0;            // $69: Pac-Man in the tunnel (I)
};

// A = the ghost's incoming direction, X/Y = the target (Pac-Man's position or the ghost's corner).
std::uint8_t ghostDecisionRun(std::uint16_t entry, std::uint8_t a, std::uint8_t x, std::uint8_t y, DecisionEnv& env);

}  // namespace pacman::core
